// A branch can be checked out in one working copy at a time. A card's branch
// is also where its prototype lives while planning, and a prototype copy that
// is still there would stop the builder from using the branch. Detaching that
// copy at the commit it is on frees the branch and changes no file, so what
// is running there carries on. Only the factory's own copies (in the folders
// it is given) are detached: a copy anywhere else is a person's, who works on
// the branch by hand, and the branch is not taken from them.
import { existsSync, realpathSync } from "node:fs";
import { relative, sep } from "node:path";
import { run } from "../processes.js";
// The branch is checked out in a copy that is not the factory's.
class BranchTaken extends Error {
    branch;
    where;
    constructor(branch, where) {
        super(`The branch ${branch} is open in ${where}, which is not one of the factory's copies.`);
        this.branch = branch;
        this.where = where;
    }
}
// The copies, other than `keep`, that have the branch checked out.
async function holders(copy, branch, keep) {
    const list = await run("git", [
        "-C",
        copy,
        "worktree",
        "list",
        "--porcelain",
    ]);
    const kept = existsSync(keep) ? realpathSync(keep) : keep;
    const found = [];
    for (const entry of list.split(/\r?\n\r?\n/)) {
        const path = /^worktree (.+)$/m.exec(entry)?.[1];
        const holds = entry.split(/\r?\n/).includes(`branch refs/heads/${branch}`);
        if (path && holds && existsSync(path) && realpathSync(path) !== kept)
            found.push(realpathSync(path));
    }
    return found;
}
function inside(path, folders) {
    return folders.some((folder) => {
        if (!existsSync(folder))
            return false;
        const from = relative(realpathSync(folder), path);
        return from !== "" && !from.startsWith(`..${sep}`) && from !== "..";
    });
}
// Where the branch is checked out outside the factory's folders (`own`);
// none when it is not.
export async function heldElsewhere(copy, branch, keep, own) {
    const found = await holders(copy, branch, keep);
    return found.find((path) => !inside(path, own)) ?? null;
}
// Frees the branch for `keep`: the factory's copies that hold it are
// detached; when a copy elsewhere holds it, nothing is touched (BranchTaken).
export async function freeBranch(copy, branch, keep, own) {
    const found = await holders(copy, branch, keep);
    const elsewhere = found.find((path) => !inside(path, own));
    if (elsewhere)
        throw new BranchTaken(branch, elsewhere);
    for (const path of found)
        await run("git", ["-C", path, "checkout", "--quiet", "--detach"]);
}
